export type KnownEventKind = (typeof knownEventKinds)[number];
const knownEventKindSet: ReadonlySet<string> = new Set(knownEventKinds);
export function isKnownEventKind(value: unknown): value is KnownEventKind {
  return typeof value === "string" && knownEventKindSet.has(value);
}
